hips": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPS-074", "label": "Study family SF-APPS-074: Gravity persistence: elite creator -> teammate PPP at lags 1-3", "score": 0.154, "reached_via": ["request matches RQC:RQC-102 (0.17); FAM:SF-APPS-074 auto_addresses_question RQC:RQC-102", "request matches METH:matched_control (0.30); FAM:SF-APPS-074 auto_uses_method METH:matched_control"], "attributes": {"observed_research_question": "Gravity persistence: elite creator -> teammate PPP at lags 1-3", "auto_outcome_status": "rejected", "observed_hypothesis": "After an elite creator's signature action, teammates score more on the team's next k possessions with the same lineup on the floor.", "observed_result": "All 8 creators horizon=0. Jokic lag-1 ATT=+0.0282 CI[-0.043,+0.099] p=0.3779. CLEAN NULL on teammate PPP. Secondary: Antetokounmpo +0.075 distinct initiators over next 3 poss (perm p=0.0002, BH 0.003) ? structure not eff [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No elite creator produces a positive lineup-matched teammate-PPP lift at any lag.", "observed_sample_and_power": "Jokic lag-1 n=1880; Giannis n=1804; Doncic n=325", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF30"}]}], "n_results": 4}

